import { BlockIframeData } from '../BlockIframeData';
import { BridgeEvent, EditedBlockBridgeEvent, EnterEditModeBridgeEvent } from '../BridgeEvent';
import { BridgeParams } from '../bridge';
import { EditableAttributes } from '../editable/parsing';
/**
 * Internal shapes for `bridge-private.ts`. Not re-exported from `src/index.ts`:
 * publishing them would freeze implementation details into the public API.
 */
/** TODO: 'deselectBlok' can be added to BridgeEvent and the other 3 can be removed */
export type BridgeEventName = BridgeEvent['action'] | 'deselectBlok' | 'deletedBlock' | 'sessionReceived' | 'viewLiveVersion';
/** `setActiveBlock` is honoured at runtime but absent from {@link BridgeParams}. */
export type BridgeConfig = Required<BridgeParams> & {
    setActiveBlock?: boolean;
};
/** TODO: can be added in BridgeConfig */
export type BridgePrivateParams = BridgeParams & Pick<BridgeConfig, 'setActiveBlock'>;
export type ComponentNames = EnterEditModeBridgeEvent['componentNames'];
/** The `_parent*` keys are unread here; `handleBlokActions` forwards them on. */
export type NavigationBreadcrumb = {
    _uid: string;
    component: string;
    _parentindex?: number;
    _parentUid?: string;
    _parentfield?: string;
    _parentName?: string;
};
/** Drops `action` so {@link EnterComponentBridgeEvent} also satisfies it. */
export type EditedBlokPayload = Omit<EditedBlockBridgeEvent, 'action'>;
export type BlokActionName = 'addBlockBefore' | 'addBlockAfter' | 'duplicateBlock' | 'copy' | 'moveForward' | 'moveBackward' | 'deleteBlock';
/** Not discriminated on `separator`: `updateActionsMenu` does not narrow that way. */
export type ActionsMenuItem = {
    order: number;
    show: () => unknown;
    separator?: boolean;
    eventFunction?: () => EventListener;
    innerHTML?: string;
    className?: string;
    element?: string;
    event?: string;
};
/** Neither shape has the `space` that {@link EditableBlockData} requires. */
export type EditActionBlokRef = EditableAttributes | Pick<BlockIframeData, 'id' | 'uid' | 'name'>;
/**
 * {@link BridgeAction} should have been used here to send away message to the Editor but we
 * needed actions for sending the message to the Editor
 */
export type OutboundMessage = {
    action: 'initialized';
    config: BridgeConfig;
} | {
    action: 'noFocus';
} | {
    action: 'ping';
} | {
    action: 'edit';
    dataC: EditActionBlokRef;
    config: BridgeConfig;
} | {
    action: BlokActionName;
    blok: Partial<NavigationBreadcrumb>;
};
export type ElementOffset = {
    top: number;
    left: number;
    width: number;
    height: number;
};
/**
 * `Extract` is `never` for the four bridgeEvent names which are not there
 * so those four accept any handler.
 */
export type BridgeCallback<Name extends BridgeEventName = BridgeEventName> = (payload: Extract<BridgeEvent, {
    action: Name;
}>) => void;
export type BridgeEventMap = {
    [Name in BridgeEventName]: BridgeCallback<Name>[];
};
/** A host-page element decorated by `enterEditmode()`, and how to undo it. */
export type DecoratedElement = {
    el: HTMLElement;
    /** Inline `min-height` before the bridge forced one; `null` if untouched. */
    previousMinHeight: string | null;
};
